@page "/settings"
@using sv_42da47a2819f4fbaa012661b643f0c72.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="nav-tabs-vertical">
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast-notification @toastType">
                @toastMessage
            </div>
        }
    </main>
</div>

@* ===== PROFILE SECTION ===== *@
@{ RenderFragment ProfileSection = __builder =>
{
    <section class="settings-section">
        <h2>Profile</h2>
        <div class="profile-layout">
            <div class="avatar-area">
                <img src="@profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@profileAvatarUrl</span>
            </div>
            <div class="profile-fields">
                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" class="form-control" @bind="profileDisplayName" />
                </div>
                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" class="form-control" @bind="profileEmail" />
                </div>
                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" class="form-control" rows="4" @bind="profileBio"></textarea>
                </div>
                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    </section>
}; }

@* ===== NOTIFICATIONS SECTION ===== *@
@{ RenderFragment NotificationsSection = __builder =>
{
    <section class="settings-section">
        <h2>Notifications</h2>
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifEmail" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifPush" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifWeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>
        </div>

        <h4>Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted" @onchange="e => ToggleMuteChannel(channel, e)" />
                    @channel
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>
}; }

@* ===== SECURITY SECTION ===== *@
@{ RenderFragment SecuritySection = __builder =>
{
    <section class="settings-section">
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
            </button>
            @if (passwordPanelExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" class="form-control" @bind="confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="error-message">@passwordError</div>
                    }
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="toggle-item security-toggle">
            <label class="toggle-label">
                <input type="checkbox" @bind="twoFactorEnabled" />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
            </label>
            <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>

        @if (securitySettings?.LastPasswordChange.HasValue == true)
        {
            <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h4>Active Sessions</h4>
        <div class="sessions-table-container">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @if (securitySettings?.Sessions != null)
                    {
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        @if (showRevokeConfirmation)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation>
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>
}; }

@* ===== APPEARANCE SECTION ===== *@
@{ RenderFragment AppearanceSection = __builder =>
{
    <section class="settings-section">
        <h2>Appearance</h2>

        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" checked="@(appearanceTheme == "Light")" @onchange='() => appearanceTheme = "Light"' />
                    Light
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" checked="@(appearanceTheme == "Dark")" @onchange='() => appearanceTheme = "Dark"' />
                    Dark
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" checked="@(appearanceTheme == "System")" @onchange='() => appearanceTheme = "System"' />
                    System
                </label>
            </div>
        </div>

        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" checked="@(appearanceFontSize == "Small")" @onchange='() => appearanceFontSize = "Small"' />
                    Small
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" checked="@(appearanceFontSize == "Medium")" @onchange='() => appearanceFontSize = "Medium"' />
                    Medium
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" checked="@(appearanceFontSize == "Large")" @onchange='() => appearanceFontSize = "Large"' />
                    Large
                </label>
            </div>
        </div>

        <div class="form-group">
            <label for="language"><strong>Language</strong></label>
            <select id="language" class="form-control" @bind="appearanceLanguage">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="appearanceCompactMode" />
                <span class="toggle-switch"></span>
                Compact Mode
            </label>
        </div>

        <h4>Live Preview</h4>
        <div class="live-preview @GetPreviewClasses()">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
            <button class="preview-button">Sample Button</button>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>
}; }

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "toast-success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private readonly List<string> allChannels = new() { "general", "marketing", "engineering", "design", "announcements" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool twoFactorEnabled;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;
    private string currentSessionId = "sess-1";

    // Appearance state
    private string appearanceTheme = "Light";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "English";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        SetProfileFields(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        notifEmail = notifs.EmailNotifications;
        notifPush = notifs.PushNotifications;
        notifWeeklyDigest = notifs.WeeklyDigest;
        mutedChannels = new List<string>(notifs.MutedChannels);

        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompactMode = appearance.CompactMode;
    }

    private void SetProfileFields(UserProfile profile)
    {
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileAvatarUrl = profile.AvatarUrl;
        profileBio = profile.Bio;
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            SetProfileFields(savedProfile);
        }
    }

    // Notifications methods
    private void ToggleMuteChannel(string channel, ChangeEventArgs e)
    {
        var isChecked = (bool)(e.Value ?? false);
        if (isChecked && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!isChecked)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifWeeklyDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private async Task UpdatePassword()
    {
        passwordError = null;

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password is required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordPanelExpanded = false;
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
        ShowToast("Session revoked.", "toast-success");
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{appearanceTheme.ToLower()} preview-font-{appearanceFontSize.ToLower()}";
        if (appearanceCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "toast-success");
    }

    // Toast
    private async void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        StateHasChanged();
        await Task.Delay(3000);
        toastMessage = null;
        StateHasChanged();
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

