    <section class="settings-section">
        <h2>Profile</h2>
        <div class="profile-layout">
            <div class="avatar-area">
                <img src="@profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@profileAvatarUrl</span>
            </div>
            <div class="profile-fields">
                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" class="form-control" @bind="profileDisplayName" />
                </div>
                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" class="form-control" @bind="profileEmail" />
                </div>
                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" class="form-control" rows="4" @bind="profileBio"></textarea>
                </div>
                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    </section>
}; }

@* ===== NOTIFICATIONS SECTION ===== *@
@{ RenderFragment NotificationsSection = __builder =>
{
    <section class="settings-section">
        <h2>Notifications</h2>
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifEmail" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifPush" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="notifWeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>
        </div>

        <h4>Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted" @onchange="e => ToggleMuteChannel(channel, e)" />
                    @channel
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>
}; }

@* ===== SECURITY SECTION ===== *@
@{ RenderFragment SecuritySection = __builder =>
{
    <section class="settings-section">
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
            </button>
            @if (passwordPanelExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" class="form-control" @bind="confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="error-message">@passwordError</div>
                    }
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="toggle-item security-toggle">
            <label class="toggle-label">
                <input type="checkbox" @bind="twoFactorEnabled" />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
            </label>
            <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>

        @if (securitySettings?.LastPasswordChange.HasValue == true)
        {
            <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h4>Active Sessions</h4>
        <div class="sessions-table-container">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @if (securitySettings?.Sessions != null)
                    {
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        @if (showRevokeConfirmation)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation>
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>
}; }

